-- 0024: NFL: Bill Murray (LAR G) torn Achilles, Week 12 vs GB (2026-11-27). Generated by scripts/weekly/build-migration.mjs.
--   New tear: Bill Murray (LAR G) torn Achilles in the Rams' Week 12 home win over the Packers on Wed 2026-11-25 at SoFi Stadium (Thanksgiving Eve, 26-13).
--   Started at left guard (first career start); injured in the second half and did not return (CBS Sports; team game recap).
--   Diagnosis: Jeremy Fowler, ESPN, Nov 27, 2026, per sources (https://x.com/JFowlerESPN/status/2126486628290179549).
--   Side and mechanism not reported. Surgery expected but not yet confirmed, so no surgery update.
--   Surface: in-game tear, from the stadium record (SoFi Stadium = artificial, Hellas Matrix).
--   Bio from the official Rams roster (6-3, 321 lb, G) and ESPN athlete 3912189 (DOB 1997-07-03). Season from settings.current_season.
-- League-qualified lookups; every statement is guarded, so re-running is a no-op.
SET NAMES utf8mb4;

-- Bill Murray (NFL LAR)
INSERT INTO players (league, first_name, last_name, slug, position, team_id)
SELECT 'NFL', 'Bill', 'Murray', 'bill-murray', 'G', (SELECT id FROM teams WHERE league = 'NFL' AND abbreviation = 'LAR')
WHERE NOT EXISTS (SELECT 1 FROM players WHERE slug = 'bill-murray');
UPDATE players SET dob = COALESCE(dob, '1997-07-03'), height_in = COALESCE(height_in, 75), weight_lb = COALESCE(weight_lb, 321), headshot_path = COALESCE(headshot_path, '/players/bill-murray.png'), team_id = COALESCE((SELECT id FROM teams WHERE league = 'NFL' AND abbreviation = 'LAR'), team_id) WHERE slug = 'bill-murray' AND league = 'NFL';

-- Tear: bill-murray Achilles 2026-11-25
INSERT INTO injuries (player_id, injury_type, injury_date, season, week, stadium_id, home_away, opponent_id, mechanism, body_side, phase, severity_notes, source)
SELECT p.id, 'Achilles', '2026-11-25', COALESCE((SELECT CAST(s.v AS UNSIGNED) FROM settings s WHERE s.k = 'current_season'), 2026),
       12, (SELECT id FROM stadiums WHERE league = 'NFL' AND slug = 'sofi-stadium'), 'home', (SELECT id FROM teams WHERE league = 'NFL' AND abbreviation = 'GB'), NULL, NULL, 'regular',
       'Started at left guard in the Rams'' 26-13 Week 12 home win over the Packers at SoFi Stadium. Injured in the second half and did not return.',
       'https://x.com/JFowlerESPN/status/2126486628290179549'
FROM players p WHERE p.slug = 'bill-murray' AND p.league = 'NFL'
  AND NOT EXISTS (SELECT 1 FROM injuries i WHERE i.player_id = p.id AND i.injury_type = 'Achilles' AND i.injury_date = '2026-11-25');

-- Update: bill-murray diagnosis 2026-11-27
INSERT INTO progress_updates (injury_id, update_date, stage, status_label, notes, source)
SELECT i.id, '2026-11-27', 'diagnosis', 'Torn Achilles confirmed', 'Jeremy Fowler of ESPN reported a torn Achilles, per sources. Murray started at left guard vs Green Bay.', 'https://x.com/JFowlerESPN/status/2126486628290179549'
FROM injuries i JOIN players p ON p.id = i.player_id
WHERE p.slug = 'bill-murray' AND p.league = 'NFL' AND i.injury_type = 'Achilles' AND i.injury_date = '2026-11-25'
  AND NOT EXISTS (SELECT 1 FROM progress_updates x WHERE x.injury_id = i.id AND x.stage = 'diagnosis' AND x.update_date = '2026-11-27');
